import { Component, OnInit } from "@angular/core";
import { Router } from "@angular/router";
import { ModalController, NavParams } from "@ionic/angular";
import { TranslateService } from "@ngx-translate/core";
import { ApiService } from "src/app/services/tnvn/services/api.service";

@Component({
  selector: 'app-observationfinalremark',
  templateUrl: './observationfinalremark.component.html',
  styleUrls: ['./observationfinalremark.component.scss'],
})

export class ObservationfinalremarkComponent implements OnInit {
  showTextarea = false;
  public teacherDetails: any;
  public submitted: Boolean = false;
  public languageType: any;
  public didDiscuss: any;
  public remarks: string='';
  public yes: any;
  public no: any;
  public submit: any;
  public giveReason: string;

  constructor(
    private modalController: ModalController,
    private _apiService: ApiService,
    navParams: NavParams,
    private _translate: TranslateService,
    public _router: Router,
  ) {    
    // this.teacherDetails = navParams.get("teacherDetails");
  }

  ngOnInit() {
    this._apiService.languageInfo.subscribe((data: any) => {
      this.languageType = data;
      this._translate.use(this.languageType);
      this._initialiseTranslation();
    });

    this.showTextarea = false;
  }

  _initialiseTranslation(): void {
    this._translate.get("didDiscuss").subscribe((res: string) => {
      this.didDiscuss = res;
    });
    this._translate.get("submit").subscribe((res: string) => {
      this.submit = res;
    });
    this._translate.get("yes").subscribe((res: string) => {
      this.yes = res;
    });
    this._translate.get("no").subscribe((res: string) => {
      this.no = res;
    });
    this._translate.get("giveReason").subscribe((res: string) => {
      this.giveReason = res;
    });
  }

  async dismiss() {
    localStorage.setItem("finalobserverfeedbacks",this.remarks);
    const onClosedData = "Wrapped Up!";
    let body1 = document.getElementsByTagName("ion-modal")[0];
    body1.classList.remove("new-info");

    await this.modalController.dismiss(this.remarks);
    this.showTextarea = false;
    // this._router.navigate(["/tnvntabs/page-route/index", { queryParams: { "pre_obs_qns_section_status": localStorage.setItem("pre_obs_qns_section_status", "1")}}])
  }
  getRemarks(remarks){      
      this.remarks = remarks

  }
  addClass() {
    this._apiService.setName("showText");
  }
}